CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(64) UNIQUE NOT NULL,name varchar(200) NOT NULL);
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code varchar(64) NOT NULL,name varchar(200) NOT NULL,status varchar(20) NOT NULL DEFAULT 'draft',timezone varchar(64) NOT NULL DEFAULT 'Asia/Kuala_Lumpur',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,code));
CREATE TABLE data_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),event_id uuid NOT NULL REFERENCES events(id),connector_type varchar(100) NOT NULL,endpoint_ref varchar(255) NOT NULL,credential_secret_ref varchar(255),status varchar(30) NOT NULL DEFAULT 'pending');
CREATE TABLE metric_readings(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),event_id uuid NOT NULL REFERENCES events(id),source_id uuid NOT NULL REFERENCES data_sources(id),metric_name varchar(120) NOT NULL,value numeric NOT NULL,unit varchar(50) NOT NULL,observed_at timestamptz NOT NULL,quality varchar(20) NOT NULL DEFAULT 'valid',correlation_id uuid NOT NULL,dedup_key varchar(255),attributes jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX ix_metric_event_time ON metric_readings(tenant_id,event_id,metric_name,observed_at DESC);
CREATE TABLE dashboard_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(64) NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,approved boolean NOT NULL DEFAULT false,UNIQUE(code,version));
CREATE TABLE dashboard_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),event_id uuid NOT NULL REFERENCES events(id),template_id uuid NOT NULL REFERENCES dashboard_templates(id),version integer NOT NULL,draft_config jsonb NOT NULL,published_config jsonb,published_at timestamptz,UNIQUE(event_id,version));
CREATE TABLE alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),event_id uuid NOT NULL REFERENCES events(id),severity varchar(20) NOT NULL,status varchar(30) NOT NULL DEFAULT 'open',title varchar(200) NOT NULL,observed_at timestamptz NOT NULL,correlation_id uuid NOT NULL);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid REFERENCES tenants(id),actor_subject varchar(255) NOT NULL,action varchar(120) NOT NULL,object_type varchar(100) NOT NULL,object_id varchar(255),result varchar(30) NOT NULL,correlation_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}'::jsonb);
